Rbase=d.xmat[baseid].reshape(3,3).copy(); pbase=d.xpos[baseid].copy()
a=s.initial_command()
def obj(name='obj'):
 return d.xpos[m.body(name+'_main').id].copy()
def site(arm='right'):
 return d.site_xpos[m.site('gripper0_'+arm+'_grip_site').id].copy()
def smat(arm='right'):
 return d.site_xmat[m.site('gripper0_'+arm+'_grip_site').id].reshape(3,3).copy()
def pose(p,R,arm='right'):
 b=0 if arm=='right' else 6
 out=a.copy(); out[b:b+3]=Rbase.T@(np.array(p)-pbase);out[b+3:b+6]=Rot.from_matrix(Rbase.T@R).as_rotvec();return out

def move(p=None,R=None,grip=None,arm='right',n=60,hold=10):
 global a
 start=a.copy();target=a.copy();b=0 if arm=='right' else 6;g=12 if arm=='right' else 18
 if p is not None:target[b:b+3]=Rbase.T@(np.asarray(p)-pbase)
 if R is not None:target[b+3:b+6]=Rot.from_matrix(Rbase.T@R).as_rotvec()
 if grip is not None:target[g:g+6]=grip
 rots=Rot.from_rotvec([start[b+3:b+6],target[b+3:b+6]])
 sl=Slerp([0,1],rots)
 for t in np.linspace(0,1,n):
  u=t*t*(3-2*t);a=start*(1-u)+target*u;a[b+3:b+6]=sl([u]).as_rotvec()[0];s.step(a)
 a=target
 for _ in range(hold):s.step(a)
 report()
def report():
 print('STEP',len(s.actions),'ok',s.success,'obj',obj(),'bowl',obj('container'),'right',site(),'left',site('left'),flush=True)
def pic(name='current'):
 Image.fromarray(s.render('egoview',(800,600))).save('/app/output/'+name+'.png')
def geom_info(arm='right'):
 S=smat(arm);p=site(arm)
 for i in range(m.ngeom):
  name=m.geom(i).name
  if name.startswith('gripper0_'+arm) and not name.endswith('_vis'):
   if m.geom_type[i]==mujoco.mjtGeom.mjGEOM_MESH:
    mi=m.geom_dataid[i];v=m.mesh_vert[m.mesh_vertadr[mi]:m.mesh_vertadr[mi]+m.mesh_vertnum[mi]]
    v=(S.T@(d.geom_xmat[i].reshape(3,3)@v.T+d.geom_xpos[i][:,None]-p[:,None])).T
    print(name,'center',S.T@(d.geom_xpos[i]-p),'box',v.min(0),v.max(0),flush=True)
def contacts():
 for c in d.contact:
  n1=m.geom(c.geom1).name;n2=m.geom(c.geom2).name
  if 'obj_' in n1 or 'obj_' in n2:print(n1,n2,c.dist,flush=True)
print('READY',flush=True);report();print('MATRICES',smat(),smat('left'),flush=True);geom_info()
